const recipes=[
 {id:'taco',name:'Tacos fiesta',emoji:'🌮',price:18,category:'street'},
 {id:'burger',name:'Burger feliz',emoji:'🍔',price:22,category:'street'},
 {id:'pizza',name:'Pizza margarita',emoji:'🍕',price:24,category:'oven'},
 {id:'cake',name:'Pastelito',emoji:'🧁',price:16,category:'sweet'},
 {id:'salad',name:'Ensalada fresca',emoji:'🥗',price:17,category:'fresh'},
 {id:'coffee',name:'Café con amor',emoji:'☕',price:12,category:'drink'},
 {id:'pancake',name:'Pancakes',emoji:'🥞',price:19,category:'sweet'},
 {id:'sushi',name:'Sushi roll',emoji:'🍣',price:26,category:'fresh'}
];
const people=['👩🏻','👨🏽','👩🏾','🧑🏻','👨🏻','👩🏼','🧔🏽','👨🏼‍🦰'];
const decorItems=[
 {id:'fern',name:'Helecho feliz',emoji:'🪴',price:35,category:'plants'},
 {id:'bouquet',name:'Flores de campo',emoji:'💐',price:50,category:'plants'},
 {id:'cactus',name:'Cactus mini',emoji:'🌵',price:28,category:'plants'},
 {id:'chair',name:'Silla de mimbre',emoji:'🪑',price:65,category:'furniture'},
 {id:'lamp',name:'Lámpara cálida',emoji:'🏮',price:80,category:'furniture'},
 {id:'table',name:'Mesita vintage',emoji:'🪵',price:95,category:'furniture'},
 {id:'art',name:'Cuadro buen rollo',emoji:'🖼️',price:45,category:'wall'},
 {id:'clock',name:'Reloj de cocina',emoji:'🕰️',price:55,category:'wall'}
];
const defaults={coins:120,level:1,xp:0,daily:0,owned:[],decor:[],sound:true};
let saved={...defaults,...JSON.parse(localStorage.getItem('queRicoSave')||'{}')};
let editConfig={name:'Un día delicioso',difficulty:'relax',customers:5,time:60,items:1,menu:['taco','burger','cake','coffee']};
let customSaved=false,game=null,tickHandle=null,toastHandle=null,shopCategory='all';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const persist=()=>{localStorage.setItem('queRicoSave',JSON.stringify(saved));updateWallet()};
function updateWallet(){$('#coins').textContent=saved.coins;$('#decor-coins').textContent=saved.coins;$('#level-number').textContent=saved.level;$('#mini-level-number').textContent=saved.level;$('#daily-label').textContent=`${Math.min(saved.daily,5)} / 5 completados`;$('#daily-progress').style.width=`${Math.min(saved.daily/5*100,100)}%`;const p=Math.min(100,saved.xp%100);$('#level-percent').textContent=`${p}%`;$('#level-progress').style.width=`${p}%`;$('#xp-label').textContent=`${saved.xp%100} / 100 XP`}
function showToast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastHandle);toastHandle=setTimeout(()=>el.classList.remove('show'),2100)}
function setView(name){$$('.view').forEach(v=>v.classList.remove('active'));$(`#${name}-view`).classList.add('active');$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name));const titles={play:'Servicio del día',editor:'Editor de niveles',restaurant:'Decorar local'};$('#crumb-title').textContent=titles[name];window.scrollTo({top:0,behavior:'smooth'})}
$$('.nav-item').forEach(btn=>btn.addEventListener('click',()=>setView(btn.dataset.view)));
function renderFood(){const available=game?game.config.menu:editConfig.menu;$('#food-grid').innerHTML=recipes.map(r=>`<button class="food-button ${available.includes(r.id)?'':'locked'}" data-food="${r.id}" ${available.includes(r.id)?'':'disabled'}><span class="food-emoji">${r.emoji}</span><strong>${r.name}</strong><small>+${r.price} 🪙</small></button>`).join('')}
function randomOrder(config){const menu=config.menu.length?config.menu:['taco'];const items=[];while(items.length<config.items){items.push(menu[Math.floor(Math.random()*menu.length)])}return {id:Math.random().toString(36).slice(2),person:people[Math.floor(Math.random()*people.length)],items,done:[],patience:100}}
function renderCustomers(){if(!game){$('#customer-row').innerHTML='';$('#orders-list').innerHTML='<div class="order-empty"><span>🪑</span>¡Tus clientes te esperan!<br>Comienza el servicio para abrir.</div>';$('#queue-count').textContent='0';return}
 const visible=game.queue.slice(0,4);$('#customer-row').innerHTML=visible.map((c,i)=>`<div class="customer"><div class="customer-order">${recipes.find(r=>r.id===c.items[c.done.length])?.emoji||'🍽️'}${c.items.length>1?` ${c.done.length+1}/${c.items.length}`:''}</div><div class="patience"><i style="width:${c.patience}%"></i></div><div class="customer-face">${c.person}</div><div class="customer-body"></div></div>`).join('');
 $('#orders-list').innerHTML=game.queue.length?game.queue.map((c,i)=>{const r=recipes.find(x=>x.id===c.items[c.done.length]);return `<div class="order-row"><div class="order-avatar">${c.person}</div><div class="order-details"><b>${i===0?'Siguiente pedido':`Cliente ${i+1}`}</b><small>${c.done.length?`Falta ${c.items.length-c.done.length} plato${c.items.length-c.done.length>1?'s':''}`:`${c.items.length} plato${c.items.length>1?'s':''} · con cariño`}</small></div><span class="order-dish">${r?.emoji||'✅'}</span></div>`}).join(''):'<div class="order-empty"><span>✨</span>¡Todos atendidos!</div>';
 $('#queue-count').textContent=game.queue.length;$('#goal-current').textContent=game.served;$('#goal-total').textContent=game.config.customers;$('#timer').textContent=`00:${String(game.time).padStart(2,'0')}`;$('#start-service').disabled=game.status==='running';$('#start-service').innerHTML=game.status==='running'?'<span>●</span> Servicio en marcha':game.status==='paused'?'<span>▶</span> Continuar servicio':'<span>▶</span> Comenzar servicio';renderFood()}
function startService(config){clearInterval(tickHandle);game={config:{...config,menu:[...config.menu]},queue:[],time:config.time,served:0,earnings:0,status:'running',serial:0};$('#goal-current').textContent='0';$('#goal-total').textContent=config.customers;$('#start-service').disabled=true;$('#start-service').innerHTML='<span>●</span> Servicio en marcha';for(let i=0;i<Math.min(3,config.customers);i++)game.queue.push(randomOrder(config));renderCustomers();tickHandle=setInterval(gameTick,1000);if(config.custom)showToast(`¡Servicio especial: ${config.name}!`);else showToast('¡A cocinar, chef!')}
function gameTick(){if(!game||game.status!=='running')return;game.time--;game.queue.forEach(c=>c.patience=Math.max(0,c.patience-(game.config.difficulty==='rush'?4:game.config.difficulty==='normal'?2.8:2)));const impatient=game.queue.filter(c=>c.patience<=0);if(impatient.length){game.queue=game.queue.filter(c=>c.patience>0);showToast('Un cliente impaciente se fue 😮‍💨')}if(game.queue.length<Math.min(3,game.config.customers-game.served)&&game.served+game.queue.length<game.config.customers)game.queue.push(randomOrder(game.config));renderCustomers();if(game.served>=game.config.customers){finishGame(true);return}if(game.time<=0)finishGame(false)}
function serve(foodId){if(!game||game.status!=='running'){showToast('¡Empieza el servicio para cocinar!');return}const customer=game.queue[0];if(!customer){showToast('¡Espera a tu siguiente cliente!');return}const expected=customer.items[customer.done.length];if(foodId!==expected){customer.patience=Math.max(0,customer.patience-12);showToast('Ups, revisa el pedido 🧾');renderCustomers();return}const recipe=recipes.find(r=>r.id===foodId);customer.done.push(foodId);let tip=customer.patience>75?5:customer.patience>40?2:0;game.earnings+=recipe.price;game.queue[0].patience=Math.min(100,customer.patience+12);if(customer.done.length>=customer.items.length){game.earnings+=tip;game.served++;saved.daily++;game.queue.shift();if(game.served+game.queue.length<game.config.customers)game.queue.push(randomOrder(game.config));showToast(tip?`¡Pedido perfecto! +${recipe.price+tip} monedas ✨`:`¡Pedido servido! +${recipe.price} monedas`)}else showToast(`¡Delicioso! Ahora prepara el siguiente plato ${recipes.find(r=>r.id===customer.items[customer.done.length]).emoji}`);persist();renderCustomers();if(game.served>=game.config.customers)finishGame(true)}
function finishGame(won){if(!game)return;clearInterval(tickHandle);game.status='ended';const served=game.served,stars=won?(game.time>game.config.time*.35?3:game.time>game.config.time*.12?2:1):served>=game.config.customers*.6?2:served>0?1:0;const bonus=won?25+stars*10:served*5;saved.coins+=game.earnings+bonus;saved.xp+=served*15;if(saved.xp>=100){const gained=Math.floor(saved.xp/100);saved.level+=gained;saved.xp%=100;showToast(`¡Subiste al nivel ${saved.level}! 🎉`)}persist();updateWallet();$('#goal-current').textContent=served;$('#timer').textContent=`00:${String(game.time).padStart(2,'0')}`;$('#start-service').disabled=false;$('#start-service').innerHTML='<span>▶</span> Comenzar servicio';$('#customer-row').innerHTML='';$('#orders-list').innerHTML='<div class="order-empty"><span>✨</span>¡Servicio terminado!</div>';$('#queue-count').textContent='0';const title=won?'¡Servicio delicioso!':'¡Buen trabajo, chef!';$('#result-modal').innerHTML=`<div class="result-emoji">${won?'🎉':'💪'}</div><h2>${title}</h2><p>${won?'¡Has hecho felices a todos tus clientes!':`Atendiste a ${served} de ${game.config.customers} clientes. ¡La próxima vez será aún mejor!`}</p><div class="result-score"><div><b>${'⭐'.repeat(stars)||'☆'}</b><span>ESTRELLAS</span></div><div><b>+${game.earnings+bonus} 🪙</b><span>GANANCIAS</span></div><div><b>+${served*15} XP</b><span>EXPERIENCIA</span></div></div><div class="modal-buttons"><button class="secondary-btn" id="close-result">Volver al local</button><button class="primary-btn" id="retry-result">Jugar otra vez ↻</button></div>`;$('#modal-backdrop').classList.add('show');$('#close-result').onclick=()=>$('#modal-backdrop').classList.remove('show');$('#retry-result').onclick=()=>{$('#modal-backdrop').classList.remove('show');startService(game.config)};renderCustomers()}
$('#start-service').addEventListener('click',()=>{if(game?.status==='running')return;if(game?.status==='paused')game.status='running';else startService({name:'Servicio del día',difficulty:'relax',customers:5,time:60,items:1,menu:['taco','burger','cake','coffee']});if(game?.status==='running'&&tickHandle===null)tickHandle=setInterval(gameTick,1000)});
$('#food-grid').addEventListener('click',e=>{const btn=e.target.closest('[data-food]');if(btn&&!btn.disabled)serve(btn.dataset.food)});
function updateEditor(){const counts={customers:$('#customers-value'),time:$('#time-value'),items:$('#items-value')};counts.customers.textContent=editConfig.customers;counts.time.textContent=editConfig.time;counts.items.textContent=editConfig.items;$('#level-name').value=editConfig.name;$('#preview-name').textContent=editConfig.name||'Mi nivel especial';$('#preview-meta').textContent=`${editConfig.customers} clientes · ${editConfig.time} segundos`;const mult={relax:1,normal:1.35,rush:1.8}[editConfig.difficulty];$('#preview-reward').textContent=`+${Math.round(editConfig.customers*15*mult)} 🪙`;const labels={relax:'Relajado',normal:'Con ritmo',rush:'Hora punta'};$('#preview-difficulty').textContent=labels[editConfig.difficulty];$('#menu-count').textContent=`${editConfig.menu.length} seleccionado${editConfig.menu.length===1?'':'s'}`;$$('.difficulty-option').forEach(b=>b.classList.toggle('selected',b.dataset.difficulty===editConfig.difficulty));$('#recipe-select-grid').innerHTML=recipes.map(r=>`<button class="recipe-choice ${editConfig.menu.includes(r.id)?'selected':''}" data-recipe="${r.id}"><span>${r.emoji}</span><b>${r.name}</b>${editConfig.menu.includes(r.id)?'<i>✓</i>':''}</button>`).join('');renderFood()}
$$('.difficulty-option').forEach(btn=>btn.addEventListener('click',()=>{editConfig.difficulty=btn.dataset.difficulty;updateEditor()}));$('#level-name').addEventListener('input',e=>{editConfig.name=e.target.value;$('#preview-name').textContent=editConfig.name||'Mi nivel especial'});
$$('[data-step]').forEach(btn=>btn.addEventListener('click',()=>{const {step,dir}=btn.dataset;if(step==='customers')editConfig.customers=Math.max(1,Math.min(12,editConfig.customers+Number(dir)));if(step==='time')editConfig.time=Math.max(30,Math.min(120,editConfig.time+Number(dir)*15));if(step==='items')editConfig.items=Math.max(1,Math.min(3,editConfig.items+Number(dir)));updateEditor()}));
$('#recipe-select-grid').addEventListener('click',e=>{const btn=e.target.closest('[data-recipe]');if(!btn)return;const id=btn.dataset.recipe;if(editConfig.menu.includes(id)){if(editConfig.menu.length===1){showToast('Elige al menos una receta 🍽️');return}editConfig.menu=editConfig.menu.filter(x=>x!==id)}else editConfig.menu.push(id);customSaved=false;updateEditor()});
$('#save-level').addEventListener('click',()=>{editConfig.name=editConfig.name.trim()||'Mi nivel especial';localStorage.setItem('queRicoCustomLevel',JSON.stringify(editConfig));customSaved=true;updateEditor();showToast('¡Tu nivel quedó guardado! 💾')});
$('#reset-level').addEventListener('click',()=>{editConfig={name:'Un día delicioso',difficulty:'relax',customers:5,time:60,items:1,menu:['taco','burger','cake','coffee']};customSaved=false;updateEditor();showToast('Configuración restablecida')});
$('#play-custom').addEventListener('click',()=>{if(editConfig.menu.length===0){showToast('Selecciona alguna receta');return}setView('play');startService({...editConfig,custom:true})});
function renderShop(){const list=shopCategory==='all'?decorItems:decorItems.filter(i=>i.category===shopCategory);$('#shop-grid').innerHTML=list.map(i=>{const owned=saved.decor.includes(i.id);return `<div class="shop-item ${owned?'owned':''}"><div class="shop-art">${i.emoji}</div><div><b>${i.name}</b><small>${owned?'Ya es tuyo':`${i.price} 🪙`}</small></div><button data-buy="${i.id}">${owned?'✓ Comprado':'Comprar'}</button></div>`}).join('');const plants=saved.decor.map(id=>decorItems.find(x=>x.id===id)).filter(Boolean);if(plants.length)$('#decor-plants').textContent=plants.map(x=>x.emoji).slice(0,3).join(' ')}
$$('.shop-tab').forEach(btn=>btn.addEventListener('click',()=>{shopCategory=btn.dataset.category;$$('.shop-tab').forEach(b=>b.classList.toggle('selected',b===btn));renderShop()}));$('#shop-grid').addEventListener('click',e=>{const btn=e.target.closest('[data-buy]');if(!btn)return;const item=decorItems.find(x=>x.id===btn.dataset.buy);if(saved.decor.includes(item.id)){showToast('¡Ya tienes este objeto!');return}if(saved.coins<item.price){showToast('Te faltan monedas. ¡A servir! 🪙');return}saved.coins-=item.price;saved.decor.push(item.id);saved.owned.push(item.id);persist();renderShop();showToast(`¡${item.name} luce genial! ✨`)});
$('#sound-toggle').addEventListener('click',e=>{saved.sound=!saved.sound;e.currentTarget.querySelector('b').textContent=saved.sound?'ON':'OFF';persist();showToast(saved.sound?'Sonido activado 🔔':'Sonido desactivado')});$('#settings').addEventListener('click',()=>showToast('¡Tu progreso se guarda automáticamente! 💾'));$('#level-pill').addEventListener('click',()=>setView('editor'));
const savedCustom=JSON.parse(localStorage.getItem('queRicoCustomLevel')||'null');if(savedCustom)editConfig={...editConfig,...savedCustom};
updateWallet();renderFood();renderCustomers();updateEditor();renderShop();if(!saved.sound)$('#sound-toggle').querySelector('b').textContent='OFF';

